package org.vef.mlkitlab;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
import java.nio.file.*;
import org.json.*;

public class ColumnMappingTest {
 static List<TableParser.Token> table(int rows){List<TableParser.Token> out=new ArrayList<>();int id=0;for(int c=0;c<7;c++)out.add(new TableParser.Token("Unknown "+c,20+c*150,30,110+c*150,45,.99f,id++));for(int r=0;r<rows;r++)for(int c=0;c<7;c++){String value=c==0?"PLACE "+r:c==1?String.format(Locale.ROOT,"%02d/01/2026",r+1):c==2?"PRODUCT "+r:c<5?String.format(Locale.ROOT,"%d.%03d",1000+r*10+c,c+r):c==5?"NOTE":"YES";out.add(new TableParser.Token(value,20+c*150,100+r*30,110+c*150,112+r*30,.99f,id++));}return out;}
 static int[] mapping={0,1,2,3,4,-1,-1};
 static ColumnLayout layout(int rows){return ColumnLayout.detect(table(rows),1100,1100);}
 @Test public void arbitraryHeadersAndAdditionalColumnsAreDetected(){ColumnLayout l=layout(20);assertEquals(7,l.columns());assertEquals(20,l.rows.size());assertTrue(l.header(0).contains("Unknown"));assertEquals(4,l.samples(0).size());MappingRows m;try{m=new MappingRows(l,mapping);}catch(Exception e){throw new RuntimeException(e);}assertEquals(100,m.result.associatedCells);}
 @Test public void splitMergedColumnAndMergeFalseSplitRestoreValues()throws Exception{ColumnLayout l=layout(5);List<Double> before=new ArrayList<>(l.bounds);l.merge(3);assertEquals(6,l.columns());l.split(3);l.move(4,before.get(4));assertEquals(before,l.bounds);MappingRows m=new MappingRows(l,mapping);assertEquals(25,m.result.associatedCells);assertEquals("1033.006",m.result.cells[3][3]);}
 @Test public void unorderedAndOutOfImageLimitsAreRejected(){ColumnLayout l=layout(5);List<Double> before=new ArrayList<>(l.bounds);try{l.move(2,l.bounds.get(1));fail();}catch(IllegalArgumentException expected){}try{l.move(0,-1);fail();}catch(IllegalArgumentException expected){}assertEquals(before,l.bounds);}
 @Test public void duplicateMissingAndUnselectedMappingsAreRejected(){for(int[] bad:new int[][]{{0,1,2,3,3,-1,-1},{0,1,2,3,-1,-1,-1},{0,1,2,3,4,-2,-1}}){try{ColumnLayout.validateMapping(bad,7);fail();}catch(IllegalArgumentException expected){assertFalse(expected.getMessage().isEmpty());}}}
 @Test public void crossingAnElementLeavesAffectedValuesInvalidWithoutSplittingDigits()throws Exception{ColumnLayout l=layout(5);TableParser.Token original=l.words.stream().filter(t->t.text.equals("1003.003")).findFirst().get();l.move(4,original.x());MappingRows m=new MappingRows(l,mapping);assertEquals("",m.result.cells[0][3]);assertEquals("invalid",m.result.status[0][3]);assertEquals("",m.result.cells[0][4]);assertTrue(m.ambiguous.length()>0);assertEquals("1003.003",original.text);}
 @Test public void invalidFourDecimalQuantityIsNotRepaired()throws Exception{ColumnLayout l=layout(5);TableParser.Token t=l.words.stream().filter(x->x.text.equals("1003.003")).findFirst().get();l.words.set(l.words.indexOf(t),new TableParser.Token("1003.0033",t.left,t.top,t.right,t.bottom,t.confidence,t.id));MappingRows m=new MappingRows(l,mapping);assertEquals("1003.0033",m.result.cells[0][3]);assertEquals("invalid",m.result.status[0][3]);assertEquals(1,m.result.invalidCells);}
 @Test public void profileRestoresConfirmedEditedLimitsButContainsNoDocumentValues()throws Exception{ColumnLayout detected=layout(5),edited=ColumnLayout.restore(detected.json(),detected.words);edited.move(3,edited.bounds.get(3)+5);JSONObject p=edited.profile(detected,mapping);assertFalse(p.toString().contains("PLACE"));assertFalse(p.toString().contains("PRODUCT"));ColumnLayout fresh=layout(5);assertArrayEquals(mapping,fresh.applyProfile(p));assertEquals(edited.bounds,fresh.bounds);}
 @Test public void incompatibleProfileNeverChangesFreshLayout()throws Exception{ColumnLayout l=layout(5);JSONObject p=l.profile(l,mapping);ColumnLayout other=layout(5);other.merge(5);List<Double> before=new ArrayList<>(other.bounds);try{other.applyProfile(p);fail();}catch(IllegalArgumentException expected){}assertEquals(before,other.bounds);}
 @Test public void unicodeTextAndOriginalFragmentsSurviveMapping()throws Exception{ColumnLayout l=layout(5);TableParser.Token t=l.cell(0,0).get(0);l.words.set(l.words.indexOf(t),new TableParser.Token("Ștefan α",t.left,t.top,t.right,t.bottom,.4f,t.id));MappingRows m=new MappingRows(l,mapping);assertEquals("ȘTEFAN Α",m.result.cells[0][0]);assertEquals("review_required",m.result.status[0][0]);assertEquals("Ștefan α",m.result.evidence[0][0].get(0).text);}
 @Test public void reorderedPhysicalColumnsUseInspectorChoicesNotHeaderNames()throws Exception{ColumnLayout l=layout(5);int[] choice={4,2,1,0,3,-1,-1};for(int c=0;c<5;c++){final int col=c;for(int row=0;row<5;row++){TableParser.Token old=l.cell(row,col).get(0);String value=choice[col]==1?String.format(Locale.ROOT,"%02d/02/2026",row+1):choice[col]>=3?"1111.111":"FREE TEXT";l.words.set(l.words.indexOf(old),new TableParser.Token(value,old.left,old.top,old.right,old.bottom,.99f,old.id));}}MappingRows m=new MappingRows(l,choice);assertEquals(25,m.result.associatedCells);assertEquals("1111.111",m.result.cells[0][4]);assertEquals("FREE TEXT",m.result.cells[0][0]);assertEquals(0,m.result.invalidCells);}
 @Test public void moreThanTwentyObservedRowsAreNotInventedOrSilentlyImported(){ColumnLayout l=layout(25);assertEquals(25,l.observedRows);assertEquals(20,l.rows.size());assertFalse(l.warnings.isEmpty());}
 @Test public void quantityAndCalendarRulesRemainUnchanged(){assertFalse(CellRetryPolicy.valid(3,"1234567"));assertFalse(CellRetryPolicy.valid(4,"1.2345"));assertTrue(CellRetryPolicy.valid(4,"1,234.567"));assertTrue(CellRetryPolicy.valid(3,"1.234,567"));assertFalse(CellRetryPolicy.valid(1,"31/02/2026"));}
 @Test public void confirmedCellCropOverridesCannotLeakIntoLegacyRereads()throws Exception{MappingRows m=new MappingRows(layout(5),mapping);try{MappingCellCrops.set(m);assertArrayEquals(m.crops[0][3],CellRetryPolicy.crop(m.result,0,3,1100,1100));assertNotNull(MappingCellCrops.active());}finally{MappingCellCrops.clear();}assertNull(MappingCellCrops.active());assertNull(MappingCellCrops.get(0,3));}
 @Test public void cumulativeJournalIncludesPreviousMachineTimeButNoInspectorWait()throws Exception{Path p=Files.createTempFile("mapping-budget", ".jsonl");long[] clock={1000000};RunJournal j=new RunJournal(p.toFile(),ProcessingBudget.clock(()->clock[0],4000));assertEquals(4000,j.elapsed());j.begin("MAPPED_ASSOCIATION",14000);clock[0]+=10999;assertEquals(14999,j.elapsed());assertEquals("",j.deadlineReason());clock[0]++;assertTrue(j.deadlineReason().startsWith("TOTAL_TIMEOUT"));Files.deleteIfExists(p);}
 @Test public void realClearPhotoWithManualMappingMatchesIndependentOracle()throws Exception{String path=System.getProperty("mlkit.clear.report",""),truthPath=System.getProperty("mlkit.clear.oracle","");assertFalse("Real fixture required",path.isEmpty());JSONObject raw=new JSONObject(new String(Files.readAllBytes(Paths.get(path)),java.nio.charset.StandardCharsets.UTF_8));long start=System.nanoTime();ColumnLayout l=ColumnLayout.detect(ColumnLayout.tokens(raw.getJSONArray("tokensInOrientedOcrPixels")),raw.getInt("ocrWidth"),raw.getInt("ocrHeight"));assertEquals(9,l.columns());assertEquals(20,l.rows.size());MappingRows mapped=new MappingRows(l,new int[]{-1,0,1,2,3,4,-1,-1,-1});double elapsed=(System.nanoTime()-start)/1e6;
  // Explicit test inspector mapping above. Oracle is loaded only after extraction.
  JSONArray truth=new JSONArray(new String(Files.readAllBytes(Paths.get(truthPath)),java.nio.charset.StandardCharsets.UTF_8));int correct=0;Set<Integer> ids=new HashSet<>();for(int r=0;r<20;r++)for(int c=0;c<5;c++){assertEquals("row="+(r+1)+" field="+c,truth.getJSONArray(r).getString(c),mapped.result.cells[r][c]);correct++;for(TableParser.Token t:mapped.result.evidence[r][c])assertTrue("No token assigned to two safe cells",ids.add(t.id));}assertEquals(100,correct);assertEquals(0,mapped.result.invalidCells);System.out.println("MAPPING REAL JSON REPLAY: 20 rows, 9 physical columns, explicit inspector mapping, 100 correct / 0 wrong / 0 missing; layout + mapped parse JVM ms="+elapsed+"; no new Android OCR executed.");
 }
 @Test public void skewedRowsAndDriftingColumnsPreserveMembership()throws Exception{List<TableParser.Token> warped=new ArrayList<>();for(TableParser.Token t:table(20)){float x=t.x(),y=t.y();float nx=x-.018f*y,ny=y+.05f*x;warped.add(new TableParser.Token(t.text,nx-45,ny-6,nx+45,ny+6,t.confidence,t.id));}ColumnLayout l=ColumnLayout.detect(warped,1200,1300);assertEquals(20,l.rows.size());assertEquals(7,l.columns());MappingRows m=new MappingRows(l,mapping);assertEquals(100,m.result.associatedCells);for(int row=0;row<20;row++)assertEquals(String.format(Locale.ROOT,"%d.%03d",1000+row*10+3,3+row),m.result.cells[row][3]);}
 @Test public void maskedCellPolygonIncludesOwnCentreAndExcludesNeighbour()throws Exception{ColumnLayout l=layout(5);MappingRows m=new MappingRows(l,mapping);double[] clip=m.clips[0][3];assertTrue(MappingCellCrops.contains(clip,(clip[0]+clip[1])/2,(clip[2]+clip[3])/2));assertFalse(MappingCellCrops.contains(clip,clip[1]+5,(clip[2]+clip[3])/2));}
 @Test public void latestHeaderfixDeviceResultPreservesAllOriginalValuesAndInvalidQuantity()throws Exception{String path=System.getProperty("mlkit.headerfix.result",System.getenv("MLKIT_HEADERFIX_RESULT"));assertNotNull("Real latest device report required",path);JSONObject source=new JSONObject(new String(Files.readAllBytes(Paths.get(path)),java.nio.charset.StandardCharsets.UTF_8));ColumnLayout l=ColumnLayout.detect(ColumnLayout.tokens(source.getJSONArray("tokensInOrientedOcrPixels")),source.getInt("ocrWidth"),source.getInt("ocrHeight"));assertEquals(9,l.columns());MappingRows m=new MappingRows(l,new int[]{-1,0,1,2,3,4,-1,-1,-1});JSONArray original=source.getJSONArray("rows");int invalid=0;for(int row=0;row<20;row++)for(int col=0;col<5;col++){JSONObject previous=original.getJSONObject(row).getJSONObject("cells").getJSONObject(TableParser.LABELS[col]);assertEquals("Original OCR must not be repaired or moved",previous.getString("value"),m.result.cells[row][col]);if(previous.getString("status").equals("invalid")){invalid++;assertEquals("invalid",m.result.status[row][col]);}}assertEquals(1,invalid);System.out.println("LATEST FOLD JSON REPLAY: 20 rows, 9 physical columns, all 100 original values unchanged, 1 invalid retained; coherent="+m.result.coherentCells+" review="+m.result.reviewCells+" invalid="+m.result.invalidCells+"; native OCR not rerun.");}

 @Test public void existingLauncherGetsOneMappingEntryAndLegacyBusyGuard()throws Exception{org.objectweb.asm.tree.ClassNode node=new org.objectweb.asm.tree.ClassNode();try(java.io.InputStream in=getClass().getClassLoader().getResourceAsStream("org/vef/mlkitlab/MainActivity.class")){assertNotNull(in);new org.objectweb.asm.ClassReader(in).accept(node,org.objectweb.asm.ClassReader.SKIP_FRAMES);}int entry=0,guard=0;for(org.objectweb.asm.tree.MethodNode m:node.methods){if(m.name.equals("diagnosticIsBusy"))guard++;if(m.name.equals("onCreate"))for(org.objectweb.asm.tree.AbstractInsnNode n:m.instructions)if(n instanceof org.objectweb.asm.tree.MethodInsnNode){org.objectweb.asm.tree.MethodInsnNode call=(org.objectweb.asm.tree.MethodInsnNode)n;if(call.owner.equals("org/vef/mlkitlab/MappingEntry")&&call.name.equals("install"))entry++;}}assertEquals(1,entry);assertEquals(1,guard);String manifest=new String(Files.readAllBytes(Paths.get(System.getProperty("mapping.manifest","app/src/main/AndroidManifest.xml"))),java.nio.charset.StandardCharsets.UTF_8);assertTrue(manifest.contains("android:name=\".MainActivity\" android:exported=\"true\""));assertTrue(manifest.contains("android:process=\":column_mapping\""));}

}
